              <span style="position: absolute; right: 0.8cqw; top: 0.85cqw; width: 0.55cqw; height: 0.55cqw; transform: translateZ(3.03cqw); border-radius: 50%; background: #f5f0e8; border: 0.12cqw solid #b85c38;"></span>
